/// What the behavior operations of fixture-timers-api run on: fixture-timers-db's
/// SQLite file, its database (D116), which `Implementations::new` takes.
#[derive(Clone)]
pub struct Behaviors {
    db: Arc<Database>,
}

impl Behaviors {
    /// The behavior operations' runner on `db`, fixture-timers-db's file.
    pub fn new(db: Arc<Database>) -> Self {
        Self { db }
    }
}

/// The core with the behaviors superschematic-rules-behaviors registers,
/// built once per process: a `Core` is `Send` and `Sync`, so one serves
/// every request and every drain.
fn core() -> &'static Core {
    static CORE: OnceLock<Core> = OnceLock::new();
    CORE.get_or_init(superschematic_rules_behaviors::core)
}

/// RULES_LAYOUT, read once per process.
///
/// # Panics
///
/// When the document does not read: the build wrote it, so that is a
/// defect of the build.
fn layout() -> &'static Layout {
    static LAYOUT: OnceLock<Layout> = OnceLock::new();
    LAYOUT.get_or_init(|| match Layout::from_json(RULES_LAYOUT) {
        Ok(layout) => layout,
        Err(err) => panic!("the behaviors' layout, RULES_LAYOUT, does not read: {err}"),
    })
}

/// The caller the core runs an operation as (D103): the route's principal
/// with the permissions it holds, each once; else a calling service
/// standing in for an end user, which holds none (D37); else no one.
fn caller(ctx: &RequestContext) -> Caller {
    if let Some(principal) = &ctx.principal {
        let mut permissions: Vec<&str> = Vec::new();
        for permission in &principal.permissions {
            if !permissions.contains(&permission.as_str()) {
                permissions.push(permission);
            }
        }
        return Caller::new(principal.subject.clone(), permissions);
    }
    if let Some(service) = &ctx.service_caller {
        return Caller::standing_in(service.deployable.clone());
    }
    Caller::new("", Vec::<String>::new())
}

/// Why an operation did not run: the core's refusal or the adapter's
/// failure, or the file's, whose writer another write held past the busy
/// timeout.
enum Failure {
    Rules(Error),
    File(orm::Error),
}

impl From<orm::Error> for Failure {
    fn from(err: orm::Error) -> Self {
        Failure::File(err)
    }
}

/// Runs `operation` of the use `use_id` on the row of `type_name` whose key
/// is `key`, with `params`, in a transaction of the file's writing
/// connection, as the request's caller, and returns its result once the
/// transaction commits. The key goes to the core in its wire form, its JSON
/// string. A refusal of the core or the adapter rolls the transaction back
/// and is the problem of its status, code, message and details; a writer
/// held past the busy timeout is a 503 the caller may try again (D58); a
/// refusal of status 500 or of no error status, any other failure of the
/// database, and a result that does not read are logged and answered as the
/// server's internal error, as the Go and TypeScript servers answer them.
pub(crate) async fn run_operation<K, P, R>(
    behaviors: &Behaviors,
    ctx: &RequestContext,
    type_name: &str,
    key: &K,
    use_id: &str,
    operation: &str,
    params: &P,
) -> Result<R, ApiError>
where
    K: Serialize + ?Sized,
    P: Serialize + ?Sized,
    R: DeserializeOwned,
{
    let key = match serde_json::to_value(key).map_err(internal)? {
        Value::String(key) => key,
        other => other.to_string(),
    };
    let params = serde_json::to_value(params).map_err(internal)?;
    let caller = caller(ctx);
    let (type_name, use_id, operation) = (
        type_name.to_owned(),
        use_id.to_owned(),
        operation.to_owned(),
    );
    let ran = behaviors
        .db
        .write_async(move |connection| {
            let host = Host::new(core(), layout());
            sqlite::run_operation(
                &host, connection, &type_name, &key, &use_id, &operation, params, caller,
            )
            .map_err(Failure::Rules)
        })
        .await;
    answer(ran)
}

/// What an operation came to, as its route answers it: its result, read as
/// the route's type, the problem of a refusal, a busy file's 503, or the
/// server's internal error.
fn answer<R: DeserializeOwned>(ran: Result<Value, Failure>) -> Result<R, ApiError> {
    match ran {
        Ok(result) => serde_json::from_value(result).map_err(internal),
        Err(Failure::Rules(Error::Refused(refusal))) if is_problem(refusal.status) => {
            Err(problem(*refusal))
        }
        Err(Failure::Rules(err)) => Err(internal(err)),
        Err(Failure::File(err @ orm::Error::Busy(_))) => Err(err.into()),
        Err(Failure::File(err)) => Err(internal(err)),
    }
}

/// Whether a refusal of `status` is answered as its problem: an error
/// status, 400 to 599, other than 500, which is the server's own.
fn is_problem(status: u16) -> bool {
    (400..=599).contains(&status) && status != 500
}

/// The problem of a refusal: its status, code, message and details.
fn problem(refusal: Refusal) -> ApiError {
    let Refusal {
        code,
        status,
        message,
        details,
        ..
    } = refusal;
    let status = StatusCode::from_u16(status).unwrap_or(StatusCode::INTERNAL_SERVER_ERROR);
    let error = ApiError::new(status, code.as_str(), message);
    match details {
        Some(details) => error.with_details(Value::Object(*details)),
        None => error,
    }
}

/// Logs `err` and answers the server's internal error, with none of its
/// text.
fn internal(err: impl std::fmt::Display) -> ApiError {
    tracing::error!(error = %err, "behavior operation failed");
    ApiError::internal("An unexpected error occurred")
}

/// The time a drain was given, in epoch milliseconds, as the core reads a
/// command's time.
fn millis(now: SystemTime) -> i64 {
    match now.duration_since(UNIX_EPOCH) {
        Ok(since) => i64::try_from(since.as_millis()).unwrap_or(i64::MAX),
        Err(_) => 0,
    }
}

/// What a command of a drain runs with (D116): the core, the layout, and
/// as its clock the time the drain was given, so the worker reads no clock
/// of its own.
fn host_at(now: SystemTime) -> Host<'static> {
    let at = millis(now);
    Host::new(core(), layout()).with_clock(move || at)
}

/// The caller TicketTimers's commands run as (D103): the worker, not a user,
/// holding the permissions its @behaviorWorker grants.
fn ticket_timers_caller() -> Caller {
    Caller::new("fixture-timers-api/TicketTimers", Vec::<String>::new())
}

/// The behavior worker TicketTimers as a worker a host drains (D116): Ticket's
/// behavior queues on fixture-timers-db's SQLite file, deadlines first, each
/// with the handler that completes its messages itself. Its `drain` takes a
/// connection of the worker's own, the time and a limit, and answers how many
/// messages it ran and when the next falls due.
pub fn ticket_timers_worker() -> Result<SqliteWorker, BoxError> {
    let deadlines = QueueDefinition::parse(TICKET_DEADLINE_QUEUE)?;
    let changes = QueueDefinition::parse(TICKET_CHANGE_QUEUE)?;
    let worker = SqliteWorker::new();
    let worker = worker.queue_in_unit(deadlines, run_ticket_timers_deadline)?;
    let worker = worker.queue_in_unit(changes, run_ticket_timers_change)?;
    Ok(worker)
}

/// Runs a claimed deadline of Ticket through the behaviors' core in the
/// unit its drain runs it in, as the worker, at the later of the time the
/// drain was given and the time it was armed to fall due at, its message
/// spent in that unit (D103). A deadline armed or cleared since the claim,
/// or of a row or a use that is gone, runs nothing, and a fire a guard
/// vetoes is released, due again in a minute, each of which it logs; a
/// refusal or a failure of the database rolls the unit back and fails the
/// message, which the queue retries after its backoff.
pub fn run_ticket_timers_deadline(
    unit: &Unit<'_>,
    claimed: Claimed<TicketDeadline>,
    now: SystemTime,
) -> Result<(), BoxError> {
    let deadline = deadline_of(&claimed.message)?;
    let claim = Claim {
        id: claimed.id.clone(),
        token: claimed.token.clone(),
    };
    let host = host_at(now);
    let run = unit.with(|connection| {
        sqlite::run_deadline(
            &host,
            connection,
            "Ticket",
            &deadline,
            ticket_timers_caller(),
            Some(&claim),
        )
    })?;
    if !matches!(run, DeadlineRun::Ran(_)) {
        tracing::info!(
            message = claimed.id.as_str(),
            why = run.why(),
            "deadline ran nothing"
        );
    }
    Ok(())
}

/// Runs a claimed change of Ticket through the behaviors' core in the unit
/// its drain runs it in, as the worker, at the time the drain was given, its
/// message spent in that unit (D103): the uses that hear the row's writes,
/// on the row as it is now, and the listeners its relations reach. A claim
/// lost runs nothing, which it logs; a refusal or a failure of the database
/// rolls the unit back and fails the message, which the queue retries after
/// its backoff.
pub fn run_ticket_timers_change(
    unit: &Unit<'_>,
    claimed: Claimed<TicketChange>,
    now: SystemTime,
) -> Result<(), BoxError> {
    let change = change_of(&claimed.message)?;
    let claim = Claim {
        id: claimed.id.clone(),
        token: claimed.token.clone(),
    };
    let host = host_at(now);
    let run = unit.with(|connection| {
        sqlite::run_change(
            &host,
            connection,
            "Ticket",
            &change,
            ticket_timers_caller(),
            Some(&claim),
        )
    })?;
    if !run.ran() {
        tracing::info!(
            message = claimed.id.as_str(),
            why = run.why(),
            "change ran nothing"
        );
    }
    Ok(())
}

/// The deadline a message of a deadline queue holds (D103): its row's key
/// in its wire form, the use, the deadline's name, the time it was armed to
/// fall due at and its payload, null when it has none.
fn deadline_of<M: Serialize>(message: &M) -> Result<Deadline, BoxError> {
    let Value::Object(mut fields) = serde_json::to_value(message)? else {
        return Err("a deadline's message is no object".into());
    };
    let mut text = |name: &str| -> Result<String, BoxError> {
        match fields.remove(name) {
            Some(Value::String(text)) => Ok(text),
            Some(other) if !other.is_null() => Ok(other.to_string()),
            _ => Err(format!("a deadline's message has no {name}").into()),
        }
    };
    let (key, use_id, name) = (text("rowKey")?, text("useId")?, text("name")?);
    let at = fields
        .get("at")
        .and_then(Value::as_i64)
        .ok_or("a deadline's message has no at")?;
    Ok(Deadline {
        key,
        use_id,
        name,
        at,
        payload: fields.remove("payload").unwrap_or(Value::Null),
    })
}

/// The change a message of a change queue holds (D103), as the table's
